$('advCancel').onclick=()=>{stop();worker?.terminate();worker=null;restoreCompleted();busy(false);$('advStatus').textContent='Cancelled. Previous completed experiment retained.';resultState('Run cancelled. Previous completed experiment remains displayed.');};
async function applyClimate(announce=true){syncSeasonControls();if($('advLocation').value==='custom'){climateError=null;return;}try{const options={days:Number($('advSeasonDays').value),stressStart:Number($('advStressStart').value),stressDays:Number($('advStressDays').value),samples:Number($('advSeasonSamples').value),location:$('advLocation').value,date:$('advDate').value,intervals:Number($('advIntervals').value),wetness:Number($('advWetness').value),co2:405,extreme:$('advExtreme').value};const x=await ResearchAPI.call('climate',{options,season:$('advPeriod').value==='season'});origin=x.origin;climateError=null;analysisRevision++;if(announce&&result){$('advStatus').textContent='Location applied; run again to update results.';resultState('Location changed. Figures still show the previous completed run; run again to update.');}if(announce&&analysis)$('globalStatus').textContent='Forcing changed; previous analysis retained.';$('advForcing').value=JSON.stringify(x.forcing,null,2);const rows=x.forcing,temps=rows.map(r=>r.airC);$('advClimateStatus').textContent=EvolutionClimate.profiles[x.origin.location].label+' · '+x.origin.date+(x.origin.seasonDays?' to '+x.origin.endDate+' · '+x.origin.seasonDays+' days · '+x.origin.blocks.length+' sampled blocks':' · repeated 24-hour day')+' · '+Math.min(...temps).toFixed(1)+'–'+Math.max(...temps).toFixed(1)+' °C. '+(x.origin.seasonDays?'Stress window: days '+x.origin.stressStart+'–'+(x.origin.stressStart+x.origin.stressDays-1)+'. Selection uses mean daily performance. ':'')+'Synthetic location climate; the evaluation period repeats across generations.';drawSeason(x);}catch(e){climateError=e.message;$('advClimateStatus').textContent='Cannot run this climate: '+e.message;}}

function syncSeasonControls(){const custom=$('advLocation').value==='custom',season=$('advPeriod').value==='season';$('advPeriod').disabled=custom;for(const id of ['advDate','advWetness','advExtreme'])$(id).disabled=custom;$('advSeasonFields').hidden=!season||custom;for(const id of ['advSeasonDays','advStressStart','advStressDays','advSeasonSamples'])$(id).disabled=!season||custom;$('advIntervals').disabled=custom||season;$('advPeriodNote').textContent=custom?'Custom rows define the evaluation period. Duration is the sum of their hours.':'The evaluated '+(season?'growing season':'day')+' repeats every generation; biological generations are a separate clock.';}
function drawSeason(x){const host=$('seasonTimeline');if(!host)return;host.replaceChildren();if(!x.origin.seasonDays){host.textContent='24-hour physiological evaluation · repeated each generation';return;}for(const block of x.origin.blocks){const span=document.createElement('span');span.style.flex=block.endDay-block.startDay;span.className=block.stress==='baseline'?'':'stressed';span.textContent=block.startDay+'–'+(block.endDay-1);span.title=block.date+' · '+block.stress+' · wetness '+block.wetness.toFixed(2);host.append(span);}host.setAttribute('aria-label',x.origin.seasonDays+' day season. Stress begins on day '+x.origin.stressStart+' and lasts '+x.origin.stressDays+' days.');}
